private class CodiconPath(val d: String, val evenOdd: Boolean)

private fun p(d: String) = CodiconPath(d, evenOdd = false)

private fun pe(d: String) = CodiconPath(d, evenOdd = true)

private fun codicon(name: String, viewport: Float, vararg paths: CodiconPath): ImageVector =
    ImageVector.Builder(
        name = "codicon.$name",
        defaultWidth = 20.dp,
        defaultHeight = 20.dp,
        viewportWidth = viewport,
        viewportHeight = viewport,
    ).apply {
        for (path in paths) {
            addPath(
                pathData = addPathNodes(path.d),
                pathFillType = if (path.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = SolidColor(Color.Black),
            )
        }
    }.build()
